from typing import Dict, Hashable, List, Mapping, Tuple, TypeVar
S = TypeVar("S", bound=Hashable)

def decompose(step: Mapping[S,S], start: S) -> Tuple[int,int,List[S]]:
    seen: Dict[S,int] = {}; orbit: List[S] = []; state = start
    while state not in seen:
        seen[state] = len(orbit); orbit.append(state); state = step[state]
    start_time = seen[state]
    return start_time, len(orbit)-start_time, orbit

if __name__ == "__main__":
    print(decompose({0:4,4:2,2:5,5:7,7:2}, 0))

from typing import Dict, Hashable, Mapping, Tuple, TypeVar
X=TypeVar("X",bound=Hashable); Y=TypeVar("Y",bound=Hashable); State=Tuple[str,Hashable]

def realize(table: Mapping[X,Y]) -> Dict[State,State]:
    step: Dict[State,State] = {}
    for x,y in table.items(): step[("in",x)] = ("out",y)
    for y in set(table.values()): step[("out",y)] = ("out",y)
    return step

if __name__ == "__main__":
    f={x:(x*x+1)%7 for x in range(7)}; step=realize(f)
    assert all(step[("in",x)] == ("out",y) for x,y in f.items())
    print(step)

